<div class="grid sm:grid-cols-2 gap-4">
    <div><label class="register-label" for="candidateFirstName">Prénom *</label><input id="candidateFirstName" name="prenom" autocomplete="given-name" required maxlength="100" class="field" placeholder="Votre prénom"></div>
    <div><label class="register-label" for="candidateLastName">Nom *</label><input id="candidateLastName" name="nom" autocomplete="family-name" required maxlength="100" class="field" placeholder="Votre nom"></div>
    <div class="sm:col-span-2"><label class="register-label" for="candidateCity">Ville *</label><input id="candidateCity" name="ville_candidat" autocomplete="address-level2" required maxlength="100" class="field" placeholder="Ex. Kinshasa"></div>
</div>
